UPDATE `level` SET `map_data` = JSON_SET(`map_data`, '$.hint', "Ключи: один настоящий и четыре фальшивки, каждый запуск они лежат по-новому. Босс подскажет, в какой стороне настоящий. Собери его, встань на линию с боссом и запусти ракету: robot.attack(5). После попадания босс бьёт по твоей клетке - уходи.") WHERE `level_id` = 6;
UPDATE `level` SET `map_data` = JSON_SET(`map_data`, '$.hint', "Настоящий ключ подскажет босс. Фальшивки отнимают 2 HP. Встань на линию с боссом и стреляй: robot.attack(5). После попадания уходи с клетки, иначе босс ответит залпом.") WHERE `level_id` = 12;
UPDATE `level` SET `map_data` = JSON_SET(`map_data`, '$.hint', "Настоящий ключ подскажет босс. Босс на H8. Между выстрелами - 3 действия: перезарядка и уход с клетки. Стреляй: robot.attack(5).") WHERE `level_id` = 18;
UPDATE `level` SET `map_data` = JSON_SET(`map_data`, '$.hint', "Настоящий ключ подскажет босс. У босса 5 HP, дальность ракеты - до 7 клеток. После попадания босс бьёт по твоей клетке - уходи. Стреляй: robot.attack(5).") WHERE `level_id` = 24;
